4.4 Create a demo ERC-20 token
This tutorial creates Demo Token (DEMO) with an initial supply of 1,000,000 tokens. It does not deploy, replace or mint official Magic Hash (MHA).Examples use Bash/WSL shell syntax, Node.js 24, Foundry 1.7.1, Solidity 0.8.30 (Paris EVM target) and OpenZeppelin Contracts 5.6.1. Use the pinned package and lockfile in the download. Paris is a compatibility target for the example, not a claim about the current network fork.Download complete contract examples4.4.1 Complete project structurecontracts/
  package.json
  package-lock.json
  foundry.toml
  src/Counter.sol
  src/DemoToken.sol
  test/Examples.t.solThe Counter example remains in place. No file is renamed while leaving stale imports in the tests.4.4.2 src/DemoToken.sol// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
contract DemoToken is ERC20 {
    constructor(address recipient) ERC20("Demo Token", "DEMO") {
        _mint(recipient, 1_000_000 * 10 ** decimals());
    }
}
4.4.3 Build and testnpm install
npm run build
npm testThe included tests cover the initial supply, recipient allocation, transfer balances and preservation of total supply.// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;
import {Counter} from "../src/Counter.sol";
import {DemoToken} from "../src/DemoToken.sol";
contract ExamplesTest {
    function testCounter() public {
        Counter c = new Counter();
        require(c.number() == 0, "initial value");
        c.increment(); c.increment();
        require(c.number() == 2, "two increments");
    }
    function testDemoSupplyAndTransfer() public {
        DemoToken d = new DemoToken(address(this));
        uint256 supply = 1_000_000 * 10 ** d.decimals();
        require(d.totalSupply() == supply, "supply");
        require(d.balanceOf(address(this)) == supply, "recipient");
        d.transfer(address(0xBEEF), 100 ether);
        require(d.balanceOf(address(0xBEEF)) == 100 ether, "transfer");
        require(d.balanceOf(address(this)) == supply - 100 ether, "sender");
        require(d.totalSupply() == supply, "no extra issuance");
    }
}
4.4.4 Deploy locallyStart Anvil as in the previous chapter, then run this against localhost only:npx forge create src/DemoToken.sol:DemoToken --rpc-url http://127.0.0.1:8545 --unlocked --from 0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266 --broadcast --constructor-args 0xf39Fd6e51aad88F6F4ce6aB8827279cffFb922664.4.5 Optional testnet deploymentAfter local tests, select the RPC and verify its chain ID as in the previous chapter. Import a dedicated test account and replace the recipient placeholder with its public address. This command broadcasts to the selected testnet.export DEMO_RECIPIENT="0xYOUR_TEST_RECIPIENT_ADDRESS"
npx forge create src/DemoToken.sol:DemoToken --rpc-url "$MAGNE_RPC_URL" --account magne-test --broadcast --constructor-args "$DEMO_RECIPIENT"Record the contract and transaction on the correct network. Mainnet deployment is outside this example; published mainnet configuration is required before any production guide applies.

4.5 Build a testnet web application
This small Vite + viem application reads a deployed Counter and can request an increment through the user’s browser wallet. It uses an explicit custom-chain definition; no OnchainKit or hidden provider setup is assumed.Download complete web example4.5.1 Requirements and filesNode.js 24, Vite 8.3.2 and viem 2.57.2. Extract the archive and enter the app folder. Use an EIP-1193 browser wallet configured for the selected testnet, with test gas and the Counter address deployed in the previous chapter.npm ci
npm run build
npm run dev4.5.2 package.json{
  "name": "magne-whitepaper-app-example",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite --host 127.0.0.1",
    "build": "vite build"
  },
  "dependencies": {
    "viem": "2.57.2"
  },
  "devDependencies": {
    "vite": "8.3.2"
  }
}4.5.3 index.html<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>MAGNE testnet counter example</title>
<body><main>
<h1>MAGNE testnet counter</h1><p>Demo only. Select your testnet and use a deployed Counter from this tutorial.</p>
<label>Network <select id="network"><option value="20250810">MAGNE L1 testnet</option><option value="20250827">M Hash L2 testnet</option></select></label>
<label>Counter address <input id="contract" placeholder="0x…" autocomplete="off"></label>
<button id="read">Read counter</button><button id="connect">Connect wallet</button><button id="increment">Increment (wallet approval)</button>
<p id="output" role="status" aria-live="polite">Ready. No transaction sent.</p>
</main><script type="module" src="/main.js"></script></body></html>4.5.4 main.jsimport { createPublicClient, createWalletClient, custom, defineChain, http, isAddress } from 'viem';
const networks = {
  20250810: defineChain({ id: 20250810, name: 'MAGNE L1 Testnet', nativeCurrency: { name: 'Test MHA', symbol: 'MHA', decimals: 18 }, rpcUrls: { default: { http: ['https://rpc.testnet.magicalhash.com'] } }, testnet: true }),
  20250827: defineChain({ id: 20250827, name: 'M Hash L2 Testnet', nativeCurrency: { name: 'Test MHA', symbol: 'MHA', decimals: 18 }, rpcUrls: { default: { http: ['https://l2-rpc.testnet.magicalhash.com'] } }, testnet: true }),
};
const abi = [
  { type: 'function', name: 'number', inputs: [], outputs: [{ type: 'uint256' }], stateMutability: 'view' },
  { type: 'function', name: 'increment', inputs: [], outputs: [], stateMutability: 'nonpayable' },
];
const output = document.querySelector('#output');
const select = document.querySelector('#network');
const field = document.querySelector('#contract');
function clients() {
  const chain = networks[Number(select.value)];
  const publicClient = createPublicClient({ chain, transport: http() });
  return { chain, publicClient };
}
function contractAddress() {
  const address = field.value.trim();
  if (!isAddress(address)) throw new Error('Enter the deployed Counter address for the selected network.');
  return address;
}
async function wallet(chain) {
  if (!window.ethereum) throw new Error('Install an EIP-1193 browser wallet first.');
  const client = createWalletClient({ chain, transport: custom(window.ethereum) });
  const [account] = await client.requestAddresses();
  if (!account) throw new Error('No wallet account selected.');
  if (await client.getChainId() !== chain.id) throw new Error('Switch the wallet to the selected testnet, then retry.');
  return { client, account };
}
let busy = false;
async function run(action) {
  if (busy) return;
  busy = true;
  document.querySelectorAll('button, input, select').forEach(e => e.disabled = true);
  output.textContent = 'Working…';
  try { await action(); } catch (error) { output.textContent = error.shortMessage || error.message || String(error); }
  finally { busy = false; document.querySelectorAll('button, input, select').forEach(e => e.disabled = false); }
}
document.querySelector('#read').onclick = () => run(async () => {
  const { publicClient } = clients();
  const value = await publicClient.readContract({ address: contractAddress(), abi, functionName: 'number' });
  output.textContent = 'Counter: ' + value.toString();
});
document.querySelector('#connect').onclick = () => run(async () => {
  const { chain } = clients();
  const { account } = await wallet(chain);
  output.textContent = 'Connected on ' + chain.name + ': ' + account;
});
document.querySelector('#increment').onclick = () => run(async () => {
  const address = contractAddress();
  const { chain, publicClient } = clients();
  const { client, account } = await wallet(chain);
  const { request } = await publicClient.simulateContract({ address, abi, functionName: 'increment', account });
  const hash = await client.writeContract(request);
  output.textContent = 'Submitted: ' + hash + '. Waiting for receipt…';
  const receipt = await publicClient.waitForTransactionReceipt({ hash, timeout: 120_000 });
  if (receipt.status !== 'success') throw new Error('Transaction reverted: ' + hash);
  output.textContent = 'Included in a testnet block: ' + hash;
});
4.5.5 Exercise the flowChoose L1 or L2, enter its Counter address and read the current value. Connect the wallet, check the account and network, then request Increment. The app simulates the call, asks the wallet to sign, and waits for the transaction receipt. Rejection, a wrong network and RPC errors are shown without recording success.4.5.6 Deployment scopeA successful receipt shows inclusion in a testnet block, not production settlement finality. Browser builds contain public configuration only. Private keys remain in the wallet; no key is entered into this app.viem Wallet Client · Testnet parameters

